function('npc', '''function npcList(){const row=dialogues.rooms.find(r=>r.investigationId===inv().id);return row?.npcs||[row?.npc||{name:'Noor',role:'Onderzoekspartner',opening:inv().beats[0].intro,topics:inv().beats.map(b=>({id:b.id,question:`Wat speelt bij ${b.title.toLowerCase()}?`,answer:b.hint,followups:[{id:'example',question:'Kun je dat verder uitleggen?',answer:b.explainAfter}]}))}];}
function npc(){return npcList().find(n=>n.name===npcFocus)||npcList()[0];}''')
function('npcPosition', '''function npcPosition(index=0){const positions=[[.34,.76],[.37,.79],[.37,.79],[.31,.63],[.4,.91],[.69,.64]],coords=(state.chapter||0)===0&&index===0?positions[state.room]:index===0?[.32,.8]:[.68,.8];return project({x:coords[0],y:coords[1]},cfg().floor);}''')
function('npcObject', '''function npcObject(){return npcList().map((n,index)=>{const p=npcPosition(index),cell=['Noor','Omar','Mila','Iris','Eva','Lena'].indexOf(n.name);return `<div class="npc-shadow" style="left:${p.x*100}%;top:${p.y*100}%"></div><button class="world-npc" data-act="approachNPC" data-name="${esc(n.name)}" aria-label="Praat met ${esc(n.name)}" style="left:${p.x*100}%;top:${p.y*100}%;--npc-sole:${cell<3?95:92}%;background-position:${[0,50,100][cell%3]}% ${cell<3?0:100}%"><span class="npc-label">${esc(n.name)} · ${icon('talk')}</span></button>`;}).join('');}''')
function('approachNPC', '''function approachNPC(b){npcFocus=b?.dataset?.name||npcList()[0].name;closeTray();const index=npcList().findIndex(n=>n.name===npcFocus),p=npcPosition(index);walkTo(p.x+.065,p.y+.025,npcPanel);speak(`Ik vlieg naar ${npc().name}.`,'Jij');}''')
function('requiredTool', '''function requiredTool(b){if(b.requiresTool)return b.requiresTool;if((state.chapter||0)!==0)return null;if(b.simulation==='electricity')return 'meter';if(state.room===2&&b.type==='connect')return 'map';if(state.room===3&&b.type==='build')return 'key';return null;}''')
function('renderNPC', '''function renderNPC(){const n=npc(),topic=n.topics.find(t=>t.id===npcTopic),follow=topic?.followups?.find(f=>f.id===npcFollow);let body=`<div class="npc-selector">${npcList().map(x=>button(esc(x.name),'switchNPC',x.name===n.name?'btn-primary':'btn-secondary',`data-name="${esc(x.name)}"`)).join('')}</div><div class="npc-line"><span class="npc-name">${esc(n.name)} · ${esc(n.role)}</span><p>${esc(follow?.answer||topic?.answer||n.opening)}</p></div>`;if(topic){body+=`<div class="npc-questions">${(topic.followups||[]).map(f=>button(esc(f.question),'npcFollow','btn-secondary',`data-id="${f.id}"`)).join('')}${button('Een andere vraag stellen','npcTopics','btn-secondary')}</div><button class="hint-toggle" data-act="saveNPC">Bewaar dit inzicht in mijn notities</button>`;}else body+=`<div class="npc-questions">${n.topics.map(t=>button(esc(t.question),'npcTopic','btn-secondary',`data-id="${t.id}"`)).join('')}</div>`;tray(`In gesprek met ${n.name}`,body,'Jij kiest wat je vraagt');}''')
function('beginFinale', '''function beginFinale(lesson=false){const current=inv();if(!lesson&&!investigated(state,current)){notify('Onderzoek eerst alle aanwijzingen.');return;}if(lesson&&chapter().investigations.some(i=>!state.rooms.includes(i.id))){notify('Rond eerst alle gebieden van deze les af.');return;}const finale=lesson?chapter().chapterFinale:current.finale;if(!finale)return;finalView={finale,key:lesson?`lesson-${state.chapter+1}`:current.id,index:0,lesson,selectedEvidence:null};renderFinale();}''')
