function('nextFinal', '''function nextFinal(){const f=finalView,slot=f.finale.slots[f.index],a=state.finalAnswers[`${f.key}:${slot.id}`];if(!a||a.evidence!==slot.evidenceBeatId||!slot.options.some(o=>o.id===a.option&&o.correct))return;if(f.index<f.finale.slots.length-1){f.index++;f.selectedEvidence=null;renderFinale();return;}if(!checkFinale(state,f.finale,f.key))return;if(f.lesson){if(!state.completedLessons.includes(chapter().lessonId))state.completedLessons.push(chapter().lessonId);if(state.chapter===0)state.finalLesson=true;persist();sound();openPanel(`Les ${state.chapter+1}: verbanden gelegd.`,`<div class="room-complete"><p class="eyebrow">Nieuwe situatie onderzocht</p><h2>Pas je inzichten toe.</h2><p>${esc(f.finale.conclusion)}</p>${chapter().knowledgeCheck?button('De afsluitende vragen','beginKnowledge'):button('Bekijk mijn route','route')}${button('Bewaar mijn onderzoeksboek','export','btn-quiet')}</div>`,'De adventure en de kennischeck vullen elkaar aan');}else{try{finishRoom(state,inv());persist();sound();render();const exit=inv().world?.exit;openPanel('De doorgang is vrij.',`<div class="room-complete"><p class="eyebrow">Oplossing onderbouwd · +120 XP</p><h2>${esc(exit?.unlockedText||inv().title)}</h2><p>${esc(f.finale.conclusion)}</p><p>${esc(exit?.destinationReason||'Je neemt het gevonden bewijs mee naar het volgende gebied.')}</p>${button(lastRoom()?`Naar de eindpuzzel van les ${state.chapter+1}`:esc(exit?.label||'Naar de volgende plek'),'nextRoom')}</div>`,'Jouw verklaring maakt de volgende stap mogelijk');}catch(e){notify(e.message);}}}''')
