function('route', '''function route(){openPanel('De route door de module.',`<p>Elke les heeft meerdere gebieden. Je onderbouwde oplossing opent steeds de volgende plaats. Je gereedschap en onderzoeksboek reizen mee.</p>${book.chapters.map((ch,k)=>{const available=admin.active||k===0||state.completedLessons.includes(book.chapters[k-1].lessonId)&&(!book.chapters[k-1].knowledgeCheck||state.knowledgePasses.includes(book.chapters[k-1].lessonId));return `<section class="route-chapter"><p class="eyebrow">Les ${k+1}</p><h3>${esc(ch.title)}</h3><div class="room-map">${ch.investigations.map((i,n)=>{const open=available&&(n===0||state.rooms.includes(ch.investigations[n-1].id)),c=cfg(n,k);return `<button class="map-room" data-act="goRoom" data-chapter="${k}" data-index="${n}" ${open?'':'disabled'}><img src="${c.image}" alt=""><div><p class="eyebrow">Gebied ${n+1} / ${ch.investigations.length} · ${state.rooms.includes(i.id)?'Doorgang vrij':open?'Te onderzoeken':'Nog gesloten'}</p><h3>${esc(c.name)}</h3><p>${i.beats.length} onderzoeksmomenten</p></div></button>`;}).join('')}</div></section>`;}).join('')}${chapter().investigations.every(i=>state.rooms.includes(i.id))?button(`De eindpuzzel van les ${state.chapter+1}`,'lessonFinal'):''}${campaign.chapters.slice(book.chapters.length).map(ch=>`<div class="lesson-info">${esc(ch.title)} · wordt gebouwd</div>`).join('')}`,'Business Ethics · adventures per les');}''')
function('adminOverview', '''function adminOverview(){openPanel('Alle gebieden van de module',`<p>Open een gebied of controleer theorie, gesprekken en puzzels. Deze preview verandert je gewone voortgang niet.</p>${book.chapters.map((ch,n)=>`<section class="admin-chapter"><p class="eyebrow">Les ${n+1}</p><h3>${esc(ch.title)}</h3><div class="room-map">${ch.investigations.map((i,k)=>`<button class="map-room" data-act="adminVisit" data-chapter="${n}" data-index="${k}"><img src="${cfg(k,n).image}" alt=""><div><h3>${esc(cfg(k,n).name)}</h3><p>${i.beats.length} onderzoeksmomenten · ${i.finale.slots.length} puzzelverbanden</p></div></button>`).join('')}</div></section>`).join('')}${campaign.chapters.slice(book.chapters.length).map(ch=>`<div class="lesson-info">${esc(ch.title)} · wordt gebouwd</div>`).join('')}`,'Beheerpreview');}''')
